using Microsoft.EntityFrameworkCore;using Mbb.Archive.Modules.Archive.Application.Abstractions;using Mbb.Archive.Modules.Archive.Application.Records.Get;using Mbb.Archive.Modules.Archive.Domain.Records;
namespace Mbb.Archive.Modules.Archive.Infrastructure.Persistence;
internal sealed class EfArchiveRepository:IArchiveRecordRepository,IArchiveQueries{private readonly ArchiveDbContext _db;public EfArchiveRepository(ArchiveDbContext db){_db=db;}public async Task AddAsync(ArchiveRecord r,CancellationToken ct)=>await _db.Records.AddAsync(r,ct);public Task<ArchiveRecord?> GetAsync(ArchiveRecordId id,CancellationToken ct)=>_db.Records.SingleOrDefaultAsync(x=>x.Id==id,ct);public Task<ArchiveRecord?> GetByDocumentVersionAsync(Guid id,CancellationToken ct)=>_db.Records.SingleOrDefaultAsync(x=>x.DocumentVersionId==id,ct);public Task<ArchiveRecordDetails?> GetAsync(Guid id,CancellationToken ct)=>_db.Records.AsNoTracking().Where(x=>x.Id==new ArchiveRecordId(id)).Select(x=>new ArchiveRecordDetails(x.Id.Value,x.DocumentId,x.DocumentVersionId,x.Status.ToString(),x.OriginalStorageKey,x.Sha256Hash,x.MimeType,x.SizeBytes,x.ClassificationCode,x.RetentionRuleCode,x.CreatedAt,x.DeclaredAt)).SingleOrDefaultAsync(ct);}
